{"content": "import pytest
import flask
from flask.testing import FlaskClient


def test_override_open_with_redirect(app, client):
    """Test that overriding FlaskClient.open with extra kwargs works
    when following redirects. Regression test for #3396."""

    class CustomClient(FlaskClient):
        def open(self, *args, **kwargs):
            kwargs.setdefault("headers", {"X-Extra": "extra value"})
            return super().open(*args, **kwargs)

    app.test_client_class = CustomClient

    @app.route("/")
    def home():
        return flask.redirect(flask.url_for("test"))

    @app.route("/test")
    def test():
        return "Hello, World!"

    c = app.test_client()
    rv = c.get("/", follow_redirects=True)
    assert rv.data == b"Hello, World!"", "path": "tests/test_testing_redirect_override.py"}
